function ogF(label, hint, ctl) { return '<div style="display:flex;flex-direction:column;gap:6px"><label style="font-weight:550">' + label + '</label>' + ctl + (hint ? '<div style="font-size:12px;color:var(--mute)">' + hint + '</div>' : '') + '</div>'; }
