  const rows = have.map((p) => '<div style="display:flex;align-items:center;gap:10px;font-size:13px"><span style="width:8px;height:8px;border-radius:50%;background:var(--accent)"></span><span style="flex-grow:1">' + p[1] + ' (' + p[0] + ')</span>' + ((L.verified || {})[p[0]] ? '<span class="mono" title="SHA-256 identical to the pinned MRC IEU 1kg.v3 panel" style="font-size:11px;color:var(--accent)">MATCHES PUBLISHED PANEL</span>' : '<span class="mono" title="SHA-256 not identical to the pinned MRC IEU 1kg.v3 panel, or not recorded. Clumping may differ from OpenGWAS." style="font-size:11px;color:var(--warn)">NOT THE PINNED PANEL</span>') + '<span class="mono" style="font-size:11px;color:var(--mute)">' + gb((L.bytes || {})[p[0]]) + '</span>' + (busy ? '' : '<button type="button" data-a="ld_remove" data-v="' + p[0] + '" aria-label="Remove the ' + p[1] + ' panel" style="border:0;background:transparent;color:var(--accent);font-size:12px;font-weight:550">Remove</button>') + '</div>').join('');
